import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Coze Programming cookbook","description":"Jump to a job: workflows, plugins, knowledge, skills, publish, Coze CLI. Every recipe links to an official page. No Doubao or Trae tutorials.","frontmatter":{"title":"Coze Programming cookbook","description":"Jump to a job: workflows, plugins, knowledge, skills, publish, Coze CLI. Every recipe links to an official page. No Doubao or Trae tutorials.","domain":"product","tags":["agent-builder"],"role":"cookbook"},"headers":[],"relativePath":"products/coze/coze-cookbook.md","filePath":"products/coze/coze-cookbook.md","lastUpdated":1787110548000}'),n={name:"products/coze/coze-cookbook.md"};function i(l,e,r,p,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="coze-programming-cookbook" tabindex="-1">Coze Programming cookbook <a class="header-anchor" href="#coze-programming-cookbook" aria-label="Permalink to &quot;Coze Programming cookbook&quot;">​</a></h1><p>You can already create a low-code agent. These are <strong>recipes</strong>. Clicks for the first agent stay in the <a href="./coze.html">tutorial</a>.</p><h2 id="build-the-workflow-first-then-hang-it-on-the-agent" tabindex="-1">Build the workflow first, then hang it on the agent <a class="header-anchor" href="#build-the-workflow-first-then-hang-it-on-the-agent" aria-label="Permalink to &quot;Build the workflow first, then hang it on the agent&quot;">​</a></h2><p>Do not stuff a fixed pipeline into the persona. Officially a workflow is “a set of executable instructions” on a canvas.</p><p>Two types (<a href="https://docs.coze.cn/guides_workflow" target="_blank" rel="noreferrer">low-code workflow</a>):</p><table tabindex="0"><thead><tr><th>Type</th><th>For</th><th>Examples</th></tr></thead><tbody><tr><td>Workflow</td><td>Sequential functions / data</td><td>Research report, poster, picture book</td></tr><tr><td>Chatflow</td><td>Conversational logic</td><td>Support, personal assistant</td></tr></tbody></table><p>Every workflow has <strong>Start</strong> and <strong>End</strong>. Wire outputs by reference. Nodes accept <code>String</code>, <code>Integer</code>, <code>Number</code>, <code>Boolean</code>, <code>Object</code>, <code>File</code>, <code>Array</code>.</p><p>A paid node that <strong>succeeds still bills</strong> if the whole workflow later fails.</p><p>Space members can create / view / copy / import by default. Edit and publish need the owner to turn on collaboration. Follow the official permission table.</p><p>Natural-language full-code workflows: <a href="https://docs.coze.cn/guides_ai_powered_workflow_development" target="_blank" rel="noreferrer">develop a workflow</a>.</p><h2 id="attach-apis-plugins" tabindex="-1">Attach APIs: plugins <a class="header-anchor" href="#attach-apis-plugins" aria-label="Permalink to &quot;Attach APIs: plugins&quot;">​</a></h2><p>A plugin is a toolset. Each tool is one API. Tools in one plugin must share a domain (<a href="https://docs.coze.cn/guides_plugin" target="_blank" rel="noreferrer">plugins</a>).</p><table tabindex="0"><thead><tr><th>Kind</th><th>Who maintains it</th><th>Billing</th></tr></thead><tbody><tr><td>Library plugin</td><td>You, this account only</td><td>Whatever the API costs</td></tr><tr><td>Official plugin</td><td>Coze Programming</td><td>Per call, credits allowed</td></tr><tr><td>Third-party plugin</td><td>Other developers</td><td>Paid usage hits <strong>cash balance</strong>, not credits</td></tr></tbody></table><p>Custom plugins: API form, IDE, JSON/YAML import, or code.</p><p>Official limits:</p><ul><li>1000 plugins per space; 30 IDE plugins per account.</li><li>100 tools per plugin.</li><li>Custom plugin QPS cap 50.</li><li>Dependency bundle ≤ 250 MB.</li><li><strong>A low-code agent or app that includes a paid third-party plugin cannot publish to Feishu Bitable, Juejin, Doubao, or some public channels.</strong></li></ul><p>In an agent, <code>{</code>-reference the plugin or it may never run. In a workflow, drop it as a node.</p><h2 id="ground-facts-with-knowledge" tabindex="-1">Ground facts with knowledge <a class="header-anchor" href="#ground-facts-with-knowledge" aria-label="Permalink to &quot;Ground facts with knowledge&quot;">​</a></h2><p>Static, shared, developer-owned content belongs in knowledge, not memory (<a href="https://docs.coze.cn/guides_knowledge" target="_blank" rel="noreferrer">knowledge</a>).</p><table tabindex="0"><thead><tr><th></th><th>Knowledge</th><th>Memory</th></tr></thead><tbody><tr><td>Who edits</td><td>Developer</td><td>End user, during chat</td></tr><tr><td>Visibility</td><td>Shareable in the space; users cannot edit</td><td>Per user; not reusable across agents</td></tr><tr><td>Rental example</td><td>Listings, compounds, policy PDFs</td><td>Preferences, watch list</td></tr></tbody></table><p>Two products:</p><ul><li><strong>Coze knowledge</strong>: text / table / image. Free quota. Good for a trial.</li><li><strong>Volcengine knowledge</strong>: enterprise scale. Upload starts billing on Volcengine. <strong>Coze credits do not apply.</strong> Deleting documents does not stop compute. Unbind and delete the collection in the Volcengine console.</li></ul><p>Flow: create or bind → attach to the agent or workflow → tune retrieval → debug.</p><h2 id="pack-an-sop-as-a-skill" tabindex="-1">Pack an SOP as a skill <a class="header-anchor" href="#pack-an-sop-as-a-skill" aria-label="Permalink to &quot;Pack an SOP as a skill&quot;">​</a></h2><p>A skill is a folder with <code>SKILL.md</code>, loaded on demand, not a always-on persona (<a href="https://docs.coze.cn/guides_skill_overview" target="_blank" rel="noreferrer">skills</a>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-skill/</span></span>
<span class="line"><span>├── SKILL.md          # required</span></span>
<span class="line"><span>├── scripts/          # optional</span></span>
<span class="line"><span>├── references/       # optional</span></span>
<span class="line"><span>└── assets/           # optional</span></span></code></pre></div><p>One-liners:</p><ul><li><strong>Prompt</strong>: global persona, every turn.</li><li><strong>Skill</strong>: SOP for a class of tasks.</li><li><strong>Workflow</strong>: fixed path.</li><li><strong>Plugin</strong>: call an API.</li><li><strong>MCP</strong>: capability interface; a skill can say when to use it.</li><li><strong>Knowledge</strong>: retrieve documents, not an operations manual.</li></ul><p>On the Coze Programming home, open the <strong>Skill</strong> tab, generate with language, preview, then <strong>deploy</strong> before Coze chat can use it. Enterprise flagship can publish to an internal skill store.</p><h2 id="generate-a-full-code-agent-with-ai-programming" tabindex="-1">Generate a full-code agent with AI programming <a class="header-anchor" href="#generate-a-full-code-agent-with-ai-programming" aria-label="Permalink to &quot;Generate a full-code agent with AI programming&quot;">​</a></h2><p>When the canvas is too small:</p><ol><li><a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a> → <strong>Agent</strong> tab.</li><li>Describe features, logic, constraints. Optionally attach files, pick Q&amp;A vs Agent mode, add skills, pick a coding model.</li><li>Submit and wait for the project and unit tests.</li><li>Preview on the right. Paste errors back, or use one-click fix.</li><li>Deploy as an API: <a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">develop an agent</a>.</li></ol><p>This spends programming-task credits, built-in integrations, and hosting after go-live. Quotas: <a href="https://docs.coze.cn/guides_vibe_coding_limit" target="_blank" rel="noreferrer">limits</a>.</p><p>If a team/enterprise member cannot see the tab, ask the super admin about feature access control.</p><h2 id="publish-where-people-already-are" tabindex="-1">Publish where people already are <a class="header-anchor" href="#publish-where-people-already-are" aria-label="Permalink to &quot;Publish where people already are&quot;">​</a></h2><p>Three channel classes (<a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">publish overview</a>):</p><ol><li><strong>Official defaults</strong>: store, Feishu, WeChat, Juejin, mini programs, API, Chat SDK.</li><li><strong>Team custom</strong>: hardware / app-store tenants, team-only. Agents must publish to <strong>API and team custom channels</strong>.</li><li><strong>Public channels</strong>: only enterprise flagship can make a channel public.</li></ol><p>Flow: pack → Coze review → channel review.</p><p>Do not:</p><ul><li>Hunt for the Doubao channel (closed 2026-07-01).</li><li>Expect to clone another store agent’s full config (store listings are private; copy structure from the <a href="https://www.coze.cn/template" target="_blank" rel="noreferrer">template store</a>).</li><li>Re-list workflows or image flows in the community (removed).</li></ul><h2 id="let-another-agent-drive-coze-cli" tabindex="-1">Let another agent drive Coze: CLI <a class="header-anchor" href="#let-another-agent-drive-coze-cli" aria-label="Permalink to &quot;Let another agent drive Coze: CLI&quot;">​</a></h2><p>Official package <strong><code>@coze/cli</code></strong>, binary <strong><code>coze</code></strong>. npm <code>latest</code> on 2026-08-19 was <code>0.3.10</code>. Flags: <code>coze --help</code> and the <a href="https://www.npmjs.com/package/@coze/cli" target="_blank" rel="noreferrer">npm page</a>.</p><p>Coze chat already embeds the CLI. In Trae / Claude Code / a terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @coze/cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --foreground-scripts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coze</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> self</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># scripts: coze self skill install --target trae</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">coze</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oauth</span></span></code></pre></div><p>Official first task:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use Coze CLI to create a web app that explains Coze CLI.</span></span>
<span class="line"><span>Send me the preview link when it is ready.</span></span></code></pre></div><p>The CLI shares Coze Programming accounts and workspaces. Installing a Skill does not grant CLI permission; it teaches the host agent when to call it.</p><h2 id="when-you-must-self-host" tabindex="-1">When you must self-host <a class="header-anchor" href="#when-you-must-self-host" aria-label="Permalink to &quot;When you must self-host&quot;">​</a></h2><p>Coze Programming <strong>does not</strong> offer private deployment (<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">FAQ</a>). Open-source path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/coze-dev/coze-studio.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coze-studio</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS / Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><p>Minimum 2 cores / 4 GB and Docker. Register at <code>http://localhost:8888/sign</code>, then add a model at <code>/admin/#model-management</code>. Read the README security warning before a public bind.</p><p>Studio is a single-node core: no commercial workspaces, org management, or multi-user collab. Eval/observability OSS is <a href="https://github.com/coze-dev/coze-loop" target="_blank" rel="noreferrer">Coze Loop</a>.</p>`,52)])])}const m=t(n,[["render",i]]);export{b as __pageData,m as default};
